// ============================================================================
// KISWAHILI GRADE 4: skills, prerequisites, leads_to and the misconception library (authoring source).
// Written offline by Claude (13 Nov 2026), no model call. Everything here is DRAFT until a native
// Kiswahili speaker who teaches Kiswahili reviews it (docs/qa/kiswahili-g4-native-check-2026-11-13.md says what to check).
// scripts/build-kiswahili-g4.mjs merges it into curriculum/kiswahili/g4.json (HOREB owns that file).
// Keys: 'SARUFI.T1_NOMINO' is the sub-strand KISW.G4.SARUFI.T1_NOMINO (exact code: the design truncates names).
// Misconception short codes start M4_ so the joined Kiswahili maps (Grade 4 and Grade 5) never clash.
// Prerequisites: 'SUB.ID' a Grade 4 skill; 'G3:SUB.letter' a Grade 3 outcome. leads: Grade 5 skills as 'SUB.ID'.
// The reviewer-facing fields are in English; examples and what a child is told are in Kiswahili sanifu.
// ============================================================================
export const TO_CONFIRM = 'common learner error; to confirm by a native Kiswahili teacher';
export const INTERFERENCE = 'English or mother-tongue influence on Kiswahili (to confirm by a native Kiswahili teacher)';

// S(sub, id, name, outcomes, mastery, forms, pre, thinking, leads)
const S = (sub, id, name, outcomes, mastery, forms, pre = [], thinking = ['recall'], leads = []) => ({ sub, id, name, outcomes, mastery, forms, pre, thinking, leads });
// M(skill, code, error, question, wrong, right, cause, reveals, help, feedback, source)
const M = (skill, code, error, question, wrong, right, cause, reveals, help, feedback, source = TO_CONFIRM) => ({ skill, code, error, example: { question, wrong_answer: wrong, correct_answer: right }, cause, reveals, help, feedback, source });

